"""For each element of the deck, find its section in the downloaded WHATWG multipage chapters
(id the-<el>-element) and print the section's chapter file and the first paragraphs that
contain the word 'represents' (the element's definition), up to the next element section.
Run: uv run --with beautifulsoup4 --with html5lib python3 <scratch>/spec_represents.py"""
import pathlib, sys
from bs4 import BeautifulSoup
D = pathlib.Path(__file__).parent / "whatwg"
ELS = ("html head title link meta style body script main header footer nav article section aside "
       "h1 p hr pre blockquote ol ul li figure figcaption div a em strong q abbr code sub sup mark "
       "time br span img iframe video audio canvas table tr td th form input button label select "
       "textarea details dialog").split()
if len(sys.argv) > 1:
    ELS = sys.argv[1:]
soups = {}
for f in sorted(D.glob("*.html")):
    if f.stem in ("index", "indices", "acknowledgements", "obsolete"):
        continue
    soups[f.stem] = BeautifulSoup(f.read_text(), "html5lib")
for el in ELS:
    sid = "the-h1,-h2,-h3,-h4,-h5,-and-h6-elements" if el == "h1" else f"the-{el}-element"
    for name, soup in soups.items():
        h = soup.find(id=sid)
        if not h:
            continue
        out = []
        for sib in h.find_next_siblings():
            if sib.name in ("h4", "h3", "h2") and sib.get("id", "").startswith("the-"):
                break
            if sib.name == "p" and "represents" in sib.get_text():
                out.append(" ".join(sib.get_text(" ").split()))
            if len(out) >= 3:
                break
        print(f"== {el}  ({name}.html#{sid})")
        for o in out:
            print("   ", o[:600])
        break
    else:
        print(f"== {el}  NOT FOUND")

"""Search Wikidata (wbsearchentities, English) for each term and print the top hits with their en and sv labels.
Run: python3 <scratch>/wd_search.py <term>...  (raw responses saved as wd_search_<n>.json)"""
import json, pathlib, sys, time, urllib.parse, urllib.request
UA = "solid-memo deck research (https://github.com/antwika/solid-memo)"
D = pathlib.Path(__file__).parent
def get(url):
    for _ in range(5):
        try:
            with urllib.request.urlopen(urllib.request.Request(url, headers={"User-Agent": UA})) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            if e.code == 429:
                time.sleep(10); continue
            raise
for n, term in enumerate(sys.argv[1:]):
    q = urllib.parse.urlencode({"action": "wbsearchentities", "search": term, "language": "en", "limit": 4, "format": "json"})
    res = get("https://www.wikidata.org/w/api.php?" + q)
    ids = [h["id"] for h in res.get("search", [])]
    if not ids:
        print(term, "-> none"); continue
    q2 = urllib.parse.urlencode({"action": "wbgetentities", "ids": "|".join(ids), "props": "labels|aliases|descriptions", "languages": "en|sv", "format": "json"})
    ent = get("https://www.wikidata.org/w/api.php?" + q2)
    (D / f"wd_search_{term.replace(' ', '_')}.json").write_text(json.dumps(ent, ensure_ascii=False, indent=1))
    print(f"## {term}")
    for i in ids:
        e = ent["entities"][i]
        lab = {l: e.get("labels", {}).get(l, {}).get("value") for l in ("en", "sv")}
        al = [a["value"] for a in e.get("aliases", {}).get("sv", [])]
        desc = e.get("descriptions", {}).get("en", {}).get("value")
        print(f"  {i} en={lab['en']!r} sv={lab['sv']!r} sv-aliases={al} | {desc}")

SELECT ?item ?itemLabel ?svLabel (GROUP_CONCAT(DISTINCT ?classLabel; separator=", ") AS ?classes) WHERE {
  ?item wdt:P31/wdt:P279* wd:Q179551 .
  ?item wdt:P31 ?class .
  ?class rdfs:label ?classLabel . FILTER(LANG(?classLabel) = "en")
  OPTIONAL { ?item rdfs:label ?svLabel . FILTER(LANG(?svLabel) = "sv") }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?item ?itemLabel ?svLabel
ORDER BY ?itemLabel
